CREATE OR REPLACE FUNCTION public.social_review(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.social_publish_queue; BEGIN IF NOT public.empyrean_is_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO q FROM public.social_publish_queue WHERE id=_id; IF q.id IS NULL THEN RAISE EXCEPTION 'not_found'; END IF; RETURN jsonb_build_object('item',to_jsonb(q),'hash',public.social_payload_hash(q),'target',(SELECT jsonb_build_object('facebook',facebook_page_id,'instagram',instagram_business_id,'hashtags',default_hashtags) FROM public.social_auto_publish_settings LIMIT 1)); END $$;
REVOKE ALL ON FUNCTION public.social_review(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.social_review(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.social_approve(_id uuid,_expected_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.social_publish_queue; BEGIN IF NOT public.empyrean_is_admin() THEN RAISE EXCEPTION 'forbidden'; END IF; SELECT * INTO q FROM public.social_publish_queue WHERE id=_id FOR UPDATE; IF q.id IS NULL OR q.status <> 'pending' THEN RAISE EXCEPTION 'social_not_pending'; END IF; IF _expected_hash IS NULL OR _expected_hash <> public.social_payload_hash(q) THEN RAISE EXCEPTION 'social_review_changed'; END IF; IF cardinality(public.aegis_scan(q.content || ' ' || array_to_string(q.hashtags,' '))) > 0 THEN RAISE EXCEPTION 'social_aegis_review_required'; END IF; PERFORM set_config('app.social_governance','rpc',true); UPDATE public.social_publish_queue SET approved_by=auth.uid(),approved_at=now(),approval_expires_at=now()+interval '72 hours',approval_hash=_expected_hash WHERE id=_id; INSERT INTO public.social_publish_events(queue_id,event_type,platform,payload) VALUES(_id,'approved',q.platform,jsonb_build_object('actor',auth.uid(),'payload_hash',_expected_hash,'expires_at',now()+interval '72 hours')); RETURN jsonb_build_object('ok',true); END $$;
REVOKE ALL ON FUNCTION public.social_approve(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.social_approve(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.social_approve(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RAISE EXCEPTION 'social_exact_review_required'; END $$;
REVOKE ALL ON FUNCTION public.social_approve(uuid) FROM PUBLIC,anon,authenticated;